[{"kind": "sent", "timestamp": "2026-07-08 07:03:47.142000+00:00", "message_id": "<db7678f2-c3f4-495d-a6d4-9a0682d87a6f@mindaptivegpt.com>", "body": "<div>Hallo Maximilian,&nbsp;</div><br><div>Ich hatte mir Praxen im Gesundheitsbereich in München angeschaut und bin auf Maximilian gestoßen. Ich hab gesehen, dass ihr Gesundheitsleistungen anbietet und bestimmt täglich einige Anfragen bekommt.&nbsp;</div><br><div>Ich arbeite derzeit mit Praxen und Kliniken in der ganzen EU zusammen und helfe ihnen, sofort auf Anfragen zu reagieren. Eine davon hat in ihren ersten 30 Tagen 22 zusätzliche Termine gebucht, allein weil die Antworten schneller kamen.&nbsp;</div><br><div>Die meisten Praxen verlieren einen ordentlichen Teil ihrer Anfragen einfach deshalb, weil niemand schnell genug antwortet. Bis jemand zurückruft, hat die Person schon bei der nächsten Klinik auf der Liste gebucht.</div><div>&nbsp;&nbsp;</div><div>Geben Sie mir kurz ein Ja, und ich schicke Ihnen mehr Infos dazu, wie das funktionieren würde.&nbsp;</div><br><div>Viele Grüße&nbsp;</div><div><div>Andrew Juran</div><div>Co-founder @ Mindaptive.ai</div></div>", "from_email": "andrew.j@mindaptivegpt.com"}, {"kind": "reply", "timestamp": "2026-07-08 07:04:33+00:00", "message_id": "<f59c80e45aae48789957fe0582299b8d@FR3P281MB2976.DEUP281.PROD.OUTLOOK.COM>", "body": "<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns:m="http://schemas.microsoft.com/office/2004/12/omml" xmlns="http://www.w3.org/TR/REC-html40">
